mapper.select:
select id, unit_no, unit_name, period_label, pay_base, personal_pay, unit_pay, total_pay, personal_reserved, memo
from ben_contribution
where benefit_type = 'UNEMPLOYMENT'

    and created_by = #{unEmployment.createdBy,jdbcType=VARCHAR}



        and period_label >= #{unEmployment.timeFrom}


        and period_label <= #{unEmployment.timeTo}


        and unit_no = #{unEmployment.unitNo}


        and memo like concat('%', #{unEmployment.demoArea}, '%')


order by period_label desc
limit #{page.recordBegin}, #{page.pageSize}

select count(id) from ben_contribution
where benefit_type = 'UNEMPLOYMENT'

    and created_by = #{unEmployment.createdBy,jdbcType=VARCHAR}



        and period_label >= #{unEmployment.timeFrom}


        and period_label <= #{unEmployment.timeTo}


        and unit_no = #{unEmployment.unitNo}


        and memo like concat('%', #{unEmployment.demoArea}, '%')
